        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                print(f"{path}.{k}")
                print_structure(v, f"{path}.{k}", depth+1)
    elif isinstance(obj, list) and len(obj) < 20:
